import{_ as l,a0 as d,w as o,s as c,ao as t,I as p,a1 as e,A as i,x as a}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const C=JSON.parse('{"title":"献给 Debian 和 Ubuntu 用户的一组实用程序 | LCTT x X-CMD","titleTemplate":false,"description":"献给 Debian 和 Ubuntu 用户的一组实用程序 | LCTT (201808) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"献给 Debian 和 Ubuntu 用户的一组实用程序 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"献给 Debian 和 Ubuntu 用户的一组实用程序 | LCTT (201808) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201808/20180523 A Set Of Useful Utilities For Debian And Ubuntu Users","title":"献给 Debian 和 Ubuntu 用户的一组实用程序","tag":"201808","desc":""},"relativePath":"201808/20180523 A Set Of Useful Utilities For Debian And Ubuntu Users.md","filePath":"[post].md"}'),r={name:"201808/20180523 A Set Of Useful Utilities For Debian And Ubuntu Users.md"};function h(g,s,b,u,k,m){const n=d("Link");return o(),c("div",null,[s[17]||(s[17]=t(`<h1 id="献给-debian-和-ubuntu-用户的一组实用程序" tabindex="-1">献给 Debian 和 Ubuntu 用户的一组实用程序 <a class="header-anchor" href="#献给-debian-和-ubuntu-用户的一组实用程序" aria-label="Permalink to “献给 Debian 和 Ubuntu 用户的一组实用程序”">​</a></h1><p><img src="https://www.ostechnix.com/wp-content/uploads/2018/05/debian-goodies-720x340.png" alt=""></p><p>你使用的是基于 Debian 的系统吗？如果是，太好了！我今天在这里给你带来了一个好消息。先向 “Debian-goodies” 打个招呼，这是一组基于 Debian 系统（比如：Ubuntu、Linux Mint）的有用工具。这些实用工具提供了一些额外的有用的命令，这些命令在基于 Debian 的系统中默认不可用。通过使用这些工具，用户可以找到哪些程序占用更多磁盘空间，更新系统后需要重新启动哪些服务，在一个软件包中搜索与模式匹配的文件，根据搜索字符串列出已安装的包等等。在这个简短的指南中，我们将讨论一些有用的 Debian 的好东西。</p><h3 id="debian-goodies-–-给-debian-和-ubuntu-用户的实用程序" tabindex="-1">Debian-goodies – 给 Debian 和 Ubuntu 用户的实用程序 <a class="header-anchor" href="#debian-goodies-–-给-debian-和-ubuntu-用户的实用程序" aria-label="Permalink to “Debian-goodies – 给 Debian 和 Ubuntu 用户的实用程序”">​</a></h3><p>debian-goodies 包可以在 Debian 和其衍生的 Ubuntu 以及其它 Ubuntu 变体（如 Linux Mint）的官方仓库中找到。要安装 debian-goodies，只需简单运行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo apt-get install debian-goodies</span></span></code></pre></div><p>debian-goodies 安装完成后，让我们继续看一看一些有用的实用程序。</p><h4 id="_1、-checkrestart" tabindex="-1">1、 checkrestart <a class="header-anchor" href="#_1、-checkrestart" aria-label="Permalink to “1、 checkrestart”">​</a></h4><p>让我从我最喜欢的 <code>checkrestart</code> 实用程序开始。安装某些安全更新时，某些正在运行的应用程序可能仍然会使用旧库。要彻底应用安全更新，你需要查找并重新启动所有这些更新。这就是 <code>checkrestart</code> 派上用场的地方。该实用程序将查找哪些进程仍在使用旧版本的库，然后，你可以重新启动服务。</p><p>在进行库更新后，要检查哪些守护进程应该被重新启动，运行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo checkrestart</span></span>
<span class="line"><span>[sudo] password for sk:</span></span>
<span class="line"><span>Found 0 processes using old versions of upgraded files</span></span></code></pre></div><p>由于我最近没有执行任何安全更新，因此没有显示任何内容。</p><p>请注意，<code>checkrestart</code> 实用程序确实运行良好。但是，有一个名为 <code>needrestart</code> 的类似的新工具可用于最新的 Debian 系统。<code>needrestart</code> 的灵感来自 <code>checkrestart</code> 实用程序，它完成了同样的工作。 <code>needrestart</code> 得到了积极维护，并支持容器（LXC、 Docker）等新技术。</p><p>以下是 <code>needrestart</code> 的特点：</p><ul><li>支持（但不要求）systemd</li><li>二进制程序的黑名单（例如：用于图形显示的显示管理器）</li><li>尝试检测挂起的内核升级</li><li>尝试检测基于解释器的守护进程所需的重启（支持 Perl、Python、Ruby）</li><li>使用钩子完全集成到 apt/dpkg 中</li></ul><p>它在默认仓库中也可以使用。所以，你可以使用如下命令安装它：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo apt-get install needrestart</span></span></code></pre></div><p>现在，你可以使用以下命令检查更新系统后需要重新启动的守护程序列表：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo needrestart</span></span>
<span class="line"><span>Scanning processes...</span></span>
<span class="line"><span>Scanning linux images...</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Running kernel seems to be up-to-date.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Failed to check for processor microcode upgrades.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>No services need to be restarted.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>No containers need to be restarted.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>No user sessions are running outdated binaries.</span></span></code></pre></div><p>好消息是 Needrestart 同样也适用于其它 Linux 发行版。例如，你可以从 Arch Linux 及其衍生版的 AUR 或者其它任何 AUR 帮助程序来安装，就像下面这样：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ yaourt -S needrestart</span></span></code></pre></div><p>在 Fedora：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dnf install needrestart</span></span></code></pre></div><h4 id="_2、-check-enhancements" tabindex="-1">2、 check-enhancements <a class="header-anchor" href="#_2、-check-enhancements" aria-label="Permalink to “2、 check-enhancements”">​</a></h4><p><code>check-enhancements</code> 实用程序用于查找那些用于增强已安装的包的软件包。此实用程序将列出增强其它包但不是必须运行它的包。你可以通过 <code>-ip</code> 或 <code>–installed-packages</code> 选项来查找增强单个包或所有已安装包的软件包。</p><p>例如，我将列出增强 gimp 包功能的包：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ check-enhancements gimp</span></span>
<span class="line"><span>gimp =&gt; gimp-data: Installed: (none) Candidate: 2.8.22-1</span></span>
<span class="line"><span>gimp =&gt; gimp-gmic: Installed: (none) Candidate: 1.7.9+zart-4build3</span></span>
<span class="line"><span>gimp =&gt; gimp-gutenprint: Installed: (none) Candidate: 5.2.13-2</span></span>
<span class="line"><span>gimp =&gt; gimp-help-ca: Installed: (none) Candidate: 2.8.2-0.1</span></span>
<span class="line"><span>gimp =&gt; gimp-help-de: Installed: (none) Candidate: 2.8.2-0.1</span></span>
<span class="line"><span>gimp =&gt; gimp-help-el: Installed: (none) Candidate: 2.8.2-0.1</span></span>
<span class="line"><span>gimp =&gt; gimp-help-en: Installed: (none) Candidate: 2.8.2-0.1</span></span>
<span class="line"><span>gimp =&gt; gimp-help-es: Installed: (none) Candidate: 2.8.2-0.1</span></span>
<span class="line"><span>gimp =&gt; gimp-help-fr: Installed: (none) Candidate: 2.8.2-0.1</span></span>
<span class="line"><span>gimp =&gt; gimp-help-it: Installed: (none) Candidate: 2.8.2-0.1</span></span>
<span class="line"><span>gimp =&gt; gimp-help-ja: Installed: (none) Candidate: 2.8.2-0.1</span></span>
<span class="line"><span>gimp =&gt; gimp-help-ko: Installed: (none) Candidate: 2.8.2-0.1</span></span>
<span class="line"><span>gimp =&gt; gimp-help-nl: Installed: (none) Candidate: 2.8.2-0.1</span></span>
<span class="line"><span>gimp =&gt; gimp-help-nn: Installed: (none) Candidate: 2.8.2-0.1</span></span>
<span class="line"><span>gimp =&gt; gimp-help-pt: Installed: (none) Candidate: 2.8.2-0.1</span></span>
<span class="line"><span>gimp =&gt; gimp-help-ru: Installed: (none) Candidate: 2.8.2-0.1</span></span>
<span class="line"><span>gimp =&gt; gimp-help-sl: Installed: (none) Candidate: 2.8.2-0.1</span></span>
<span class="line"><span>gimp =&gt; gimp-help-sv: Installed: (none) Candidate: 2.8.2-0.1</span></span>
<span class="line"><span>gimp =&gt; gimp-plugin-registry: Installed: (none) Candidate: 7.20140602ubuntu3</span></span>
<span class="line"><span>gimp =&gt; xcftools: Installed: (none) Candidate: 1.0.7-6</span></span></code></pre></div><p>要列出增强所有已安装包的，请运行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ check-enhancements -ip</span></span>
<span class="line"><span>autoconf =&gt; autoconf-archive: Installed: (none) Candidate: 20170928-2</span></span>
<span class="line"><span>btrfs-progs =&gt; snapper: Installed: (none) Candidate: 0.5.4-3</span></span>
<span class="line"><span>ca-certificates =&gt; ca-cacert: Installed: (none) Candidate: 2011.0523-2</span></span>
<span class="line"><span>cryptsetup =&gt; mandos-client: Installed: (none) Candidate: 1.7.19-1</span></span>
<span class="line"><span>dpkg =&gt; debsig-verify: Installed: (none) Candidate: 0.18</span></span>
<span class="line"><span>[...]</span></span></code></pre></div><h4 id="_3、-dgrep" tabindex="-1">3、 dgrep <a class="header-anchor" href="#_3、-dgrep" aria-label="Permalink to “3、 dgrep”">​</a></h4><p>顾名思义，<code>dgrep</code> 用于根据给定的正则表达式搜索制指定包的所有文件。例如，我将在 Vim 包中搜索包含正则表达式 “text” 的文件。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dgrep &quot;text&quot; vim</span></span>
<span class="line"><span>Binary file /usr/bin/vim.tiny matches</span></span>
<span class="line"><span>/usr/share/doc/vim-tiny/copyright: that they must include this license text. You can also distribute</span></span>
<span class="line"><span>/usr/share/doc/vim-tiny/copyright: include this license text. You are also allowed to include executables</span></span>
<span class="line"><span>/usr/share/doc/vim-tiny/copyright: 1) This license text must be included unmodified.</span></span>
<span class="line"><span>/usr/share/doc/vim-tiny/copyright: text under a) applies to those changes.</span></span>
<span class="line"><span>/usr/share/doc/vim-tiny/copyright: context diff. You can choose what license to use for new code you</span></span>
<span class="line"><span>/usr/share/doc/vim-tiny/copyright: context diff will do. The e-mail address to be used is</span></span>
<span class="line"><span>/usr/share/doc/vim-tiny/copyright: On Debian systems, the complete text of the GPL version 2 license can be</span></span>
<span class="line"><span>[...]</span></span></code></pre></div><p><code>dgrep</code> 支持大多数 <code>grep</code> 的选项。参阅以下指南以了解 <code>grep</code> 命令。</p>`,33)),p("ul",null,[p("li",null,[e(n,{href:"https://www.ostechnix.com/the-grep-command-tutorial-with-examples-for-beginners/"},{default:i(()=>[...s[0]||(s[0]=[a("献给初学者的 Grep 命令教程",-1)])]),_:1})])]),s[18]||(s[18]=t(`<h4 id="_4、-dglob" tabindex="-1">4、 dglob <a class="header-anchor" href="#_4、-dglob" aria-label="Permalink to “4、 dglob”">​</a></h4><p><code>dglob</code> 实用程序生成与给定模式匹配的包名称列表。例如，找到与字符串 “vim” 匹配的包列表。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dglob vim</span></span>
<span class="line"><span>vim-tiny:amd64</span></span>
<span class="line"><span>vim:amd64</span></span>
<span class="line"><span>vim-common:all</span></span>
<span class="line"><span>vim-runtime:all</span></span></code></pre></div><p>默认情况下，<code>dglob</code> 将仅显示已安装的软件包。如果要列出所有包（包括已安装的和未安装的），使用 <code>-a</code> 标志。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dglob vim -a</span></span></code></pre></div><h4 id="_5、-debget" tabindex="-1">5、 debget <a class="header-anchor" href="#_5、-debget" aria-label="Permalink to “5、 debget”">​</a></h4><p><code>debget</code> 实用程序将在 APT 的数据库中下载一个包的 .deb 文件。请注意，它只会下载给定的包，不包括依赖项。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ debget nano</span></span>
<span class="line"><span>Get:1 http://in.archive.ubuntu.com/ubuntu bionic/main amd64 nano amd64 2.9.3-2 [231 kB]</span></span>
<span class="line"><span>Fetched 231 kB in 2s (113 kB/s)</span></span></code></pre></div><h4 id="_6、-dpigs" tabindex="-1">6、 dpigs <a class="header-anchor" href="#_6、-dpigs" aria-label="Permalink to “6、 dpigs”">​</a></h4><p>这是此次集合中另一个有用的实用程序。<code>dpigs</code> 实用程序将查找并显示那些占用磁盘空间最多的已安装包。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ dpigs</span></span>
<span class="line"><span>260644 linux-firmware</span></span>
<span class="line"><span>167195 linux-modules-extra-4.15.0-20-generic</span></span>
<span class="line"><span>75186 linux-headers-4.15.0-20</span></span>
<span class="line"><span>64217 linux-modules-4.15.0-20-generic</span></span>
<span class="line"><span>55620 snapd</span></span>
<span class="line"><span>31376 git</span></span>
<span class="line"><span>31070 libicu60</span></span>
<span class="line"><span>28420 vim-runtime</span></span>
<span class="line"><span>25971 gcc-7</span></span>
<span class="line"><span>24349 g++-7</span></span></code></pre></div><p>如你所见，linux-firmware 包占用的磁盘空间最多。默认情况下，它将显示占用磁盘空间的 <strong>前 10 个</strong>包。如果要显示更多包，例如 20 个，运行以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ dpigs -n 20</span></span></code></pre></div><h4 id="_7-debman" tabindex="-1">7. debman <a class="header-anchor" href="#_7-debman" aria-label="Permalink to “7. debman”">​</a></h4><p><code>debman</code> 实用程序允许你轻松查看二进制文件 .deb 中的手册页而不提取它。你甚至不需要安装 .deb 包。以下命令显示 nano 包的手册页。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ debman -f nano_2.9.3-2_amd64.deb nano</span></span></code></pre></div><p>如果你没有 .deb 软件包的本地副本，使用 <code>-p</code> 标志下载并查看包的手册页。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ debman -p nano nano</span></span></code></pre></div><p><strong>建议阅读：</strong></p>`,19)),p("ul",null,[p("li",null,[e(n,{href:"https://www.ostechnix.com/3-good-alternatives-man-pages-every-linux-user-know/"},{default:i(()=>[...s[1]||(s[1]=[a("每个 Linux 用户都应该知道的 3 个 man 的替代品",-1)])]),_:1})])]),s[19]||(s[19]=t(`<h4 id="_8、-debmany" tabindex="-1">8、 debmany <a class="header-anchor" href="#_8、-debmany" aria-label="Permalink to “8、 debmany”">​</a></h4><p>安装的 Debian 包不仅包含手册页，还包括其它文件，如确认、版权和自述文件等。<code>debmany</code> 实用程序允许你查看和读取那些文件。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ debmany vim</span></span></code></pre></div><p><img src="http://www.ostechnix.com/wp-content/uploads/2018/05/debmany.png" alt=""></p><p>使用方向键选择要查看的文件，然后按回车键查看所选文件。按 <code>q</code> 返回主菜单。</p><p>如果未安装指定的软件包，<code>debmany</code> 将从 APT 数据库下载并显示手册页。应安装 <code>dialog</code> 包来阅读手册页。</p><h4 id="_9、-popbugs" tabindex="-1">9、 popbugs <a class="header-anchor" href="#_9、-popbugs" aria-label="Permalink to “9、 popbugs”">​</a></h4><p>如果你是开发人员，<code>popbugs</code> 实用程序将非常有用。它将根据你使用的包显示一个定制的发布关键 bug 列表（使用 popularity-contest 数据）。对于那些不关心的人，popularity-contest 包设置了一个 cron （定时）任务，它将定期匿名向 Debian 开发人员提交有关该系统上最常用的 Debian 软件包的统计信息。这些信息有助于 Debian 做出决定，例如哪些软件包应该放在第一张 CD 上。它还允许 Debian 改进未来的发行版本，以便为新用户自动安装最流行的软件包。</p><p>要生成严重 bug 列表并在默认 Web 浏览器中显示结果，运行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ popbugs</span></span></code></pre></div><p>此外，你可以将结果保存在文件中，如下所示。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ popbugs --output=bugs.txt</span></span></code></pre></div><h4 id="_10、-which-pkg-broke" tabindex="-1">10、 which-pkg-broke <a class="header-anchor" href="#_10、-which-pkg-broke" aria-label="Permalink to “10、 which-pkg-broke”">​</a></h4><p>此命令将显示给定包的所有依赖项以及安装每个依赖项的时间。通过使用此信息，你可以在升级系统或软件包之后轻松找到哪个包可能会在什么时间损坏了另一个包。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ which-pkg-broke vim</span></span>
<span class="line"><span>Package &lt;debconf-2.0&gt; has no install time info</span></span>
<span class="line"><span>debconf Wed Apr 25 08:08:40 2018</span></span>
<span class="line"><span>gcc-8-base:amd64 Wed Apr 25 08:08:41 2018</span></span>
<span class="line"><span>libacl1:amd64 Wed Apr 25 08:08:41 2018</span></span>
<span class="line"><span>libattr1:amd64 Wed Apr 25 08:08:41 2018</span></span>
<span class="line"><span>dpkg Wed Apr 25 08:08:41 2018</span></span>
<span class="line"><span>libbz2-1.0:amd64 Wed Apr 25 08:08:41 2018</span></span>
<span class="line"><span>libc6:amd64 Wed Apr 25 08:08:42 2018</span></span>
<span class="line"><span>libgcc1:amd64 Wed Apr 25 08:08:42 2018</span></span>
<span class="line"><span>liblzma5:amd64 Wed Apr 25 08:08:42 2018</span></span>
<span class="line"><span>libdb5.3:amd64 Wed Apr 25 08:08:42 2018</span></span>
<span class="line"><span>[...]</span></span></code></pre></div><h4 id="_11、-dhomepage" tabindex="-1">11、 dhomepage <a class="header-anchor" href="#_11、-dhomepage" aria-label="Permalink to “11、 dhomepage”">​</a></h4><p><code>dhomepage</code> 实用程序将在默认 Web 浏览器中显示给定包的官方网站。例如，以下命令将打开 Vim 编辑器的主页。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ dhomepage vim</span></span></code></pre></div><p>这就是全部了。Debian-goodies 是你武器库中必备的工具。即使我们不经常使用所有这些实用程序，但它们值得学习，我相信它们有时会非常有用。</p><p>我希望这很有用。更多好东西要来了。敬请关注！</p><p>干杯!</p><hr>`,22)),p("p",null,[s[3]||(s[3]=a("via: ",-1)),e(n,{href:"https://www.ostechnix.com/debian-goodies-a-set-of-useful-utilities-for-debian-and-ubuntu-users/"},{default:i(()=>[...s[2]||(s[2]=[a("https://www.ostechnix.com/debian-goodies-a-set-of-useful-utilities-for-debian-and-ubuntu-users/",-1)])]),_:1})]),p("p",null,[s[8]||(s[8]=a("作者：",-1)),e(n,{href:"https://www.ostechnix.com/author/sk/"},{default:i(()=>[...s[4]||(s[4]=[a("SK",-1)])]),_:1}),s[9]||(s[9]=a(" 选题：",-1)),e(n,{href:"https://github.com/lujun9972"},{default:i(()=>[...s[5]||(s[5]=[a("lujun9972",-1)])]),_:1}),s[10]||(s[10]=a(" 译者：",-1)),e(n,{href:"https://github.com/MjSeven"},{default:i(()=>[...s[6]||(s[6]=[a("MjSeven",-1)])]),_:1}),s[11]||(s[11]=a(" 校对：",-1)),e(n,{href:"https://github.com/wxy"},{default:i(()=>[...s[7]||(s[7]=[a("wxy",-1)])]),_:1})]),p("p",null,[s[14]||(s[14]=a("本文由 ",-1)),e(n,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...s[12]||(s[12]=[a("LCTT",-1)])]),_:1}),s[15]||(s[15]=a(" 原创编译，",-1)),e(n,{href:"https://linux.cn/"},{default:i(()=>[...s[13]||(s[13]=[a("Linux中国",-1)])]),_:1}),s[16]||(s[16]=a(" 荣誉推出",-1))])])}const x=l(r,[["render",h]]);export{C as __pageData,x as default};
